  function resolveSlug(){
    var h=(location.hash||'#/home').replace('#/','').split('?')[0].replace(/\/+$/,'');
    /* Clean-URL deep links: /gun-safe-movers/ (and every other canonical path, plus plain slugs)
       must open that page, not home. The router previously read only the hash, so every
       canonical URL loaded home. Map the pathname to a page slug first, when no hash is set. */
    if((!location.hash || location.hash==='#/home') && location.pathname && location.pathname!=='/'){
      var path=location.pathname.replace(/^\/|\/$/g,'');
      var byPath={}; for(var k in pageMeta){ if(pageMeta[k].canonical){ var cp=pageMeta[k].canonical.replace('https://theflatratemovers.com/','').replace(/\/$/,''); if(cp) byPath[cp]=k; } byPath[k]=k; }
      if(byPath[path]) h=byPath[path];
    }
    return h;
  }
  function route(){
    var h=resolveSlug();
    if(redirects[h]){ location.hash='#/'+redirects[h]; return; }
    if(pages.indexOf(h)<0) h='home';
    if(!document.getElementById('page-'+h)){ ensurePage(h); return; }
    finishRoute(h);
  }
